# REVIEWED
# problem P-e1102e (generated by sonnet): For a set $A\subseteq\mathbb N_0$ let $r_A(n)=|\{(a,a')\in A^2: a\le a',\ a+a'=n\}|$. Let $R$ be the least integer such that some explicit (e.g. polynomial-time computable) set $A\subseteq\mathbb N_0$ satisfies $A+A=\mathbb N_0$ and $r_A(n)\le R$ for all $n$. Erdős–Turán-type heuristics suggest no b
# finite_form: Find A ⊆ {0,1,...,400} such that every n in {0,...,400} has between 1 and 3 unordered representations n=a+a' with a≤a' in A.
# candidate_format: A JSON array of distinct integers in the range 0 to 400.

def check(candidate) -> bool:
    try:
        if not isinstance(candidate, list) or len(candidate) > 401:
            return False
        for x in candidate:
            if type(x) is not int or x < 0 or x > 400:
                return False
        if len(set(candidate)) != len(candidate):
            return False
        a = sorted(candidate)
        cnt = [0] * 401
        for i in range(len(a)):
            for j in range(i, len(a)):
                s = a[i] + a[j]
                if s > 400:
                    break
                cnt[s] += 1
        return all(1 <= c <= 3 for c in cnt)
    except Exception:
        return False
